import {validateMessage} from './validation.js';

describe('list_sessions validation', () => {
  it('accepts a bare list_sessions frame', () => {
    const result = validateMessage({type: 'list_sessions'});

    expect(result).toEqual({
      valid: true,
      data: {type: 'list_sessions'},
    });
  });

  it('accepts list_sessions with limit and before', () => {
    const before = {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'};
    const result = validateMessage({type: 'list_sessions', limit: 10, before});

    expect(result).toEqual({
      valid: true,
      data: {type: 'list_sessions', limit: 10, before},
    });
  });

  it('rejects list_sessions with invalid limit', () => {
    const cases = [
      {limit: 'ten', error: /non-negative integer/},
      {limit: -1, error: /non-negative integer/},
      {limit: 1.5, error: /non-negative integer/},
    ];

    for (const {limit, error} of cases) {
      const result = validateMessage({type: 'list_sessions', limit});
      expect(result).toMatchObject({valid: false, error: expect.stringMatching(error)});
    }
  });

  it('rejects list_sessions with invalid before', () => {
    const cases = [
      {before: 'not-an-object', error: /before must be an object/},
      {before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: ''}, error: /sessionId must be 1-128/},
      {before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'a'.repeat(129)}, error: /sessionId must be 1-128/},
      {before: {updatedAt: 'not-a-date', sessionId: 's1'}, error: /valid date/},
      {before: {updatedAt: true, sessionId: 's1'}, error: /string or number/},
    ];

    for (const {before, error} of cases) {
      const result = validateMessage({type: 'list_sessions', before});
      expect(result).toMatchObject({valid: false, error: expect.stringMatching(error)});
    }
  });

  it('strips unknown fields like userId', () => {
    const result = validateMessage({type: 'list_sessions', userId: 'u2', limit: 10});

    expect(result).toEqual({
      valid: true,
      data: {type: 'list_sessions', limit: 10},
    });
  });
});

